insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 7, 'Então aqueles cinco homens se partiram, e vieram a Laís: e viram que o povo que habitava nela estava seguro, ocioso e confiante, conforme o costume dos de Sidom; não havia ninguém naquela região que os perturbasse em coisa alguma; além disso, os sidônios estavam distantes, e não tinham negócios com ninguém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 8, 'Voltando, pois, eles a seus irmãos em Zorá e Estaol, seus irmãos lhes disseram: Que há? e eles responderam:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 9, 'Levantai-vos, subamos contra eles; porque nós exploramos a região, e vimos que é muito boa: e vós vos estais quietos? Não sejais preguiçosos em vos dispor em marcha para ir a possuir a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 10, 'Quando ali chegardes, vereis a uma gente segura, e a uma terra ampla; pois que Deus a entregou em vossas mãos; lugar de onde não há falta de coisa que seja na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 11, 'E partindo os de Dã dali, de Zorá e de Estaol, seiscentos homens armados de armas de guerra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 12, 'Foram e assentaram acampamento em Quriate-Jearim, em Judá; de onde aquele lugar foi chamado o campo de Dã, até hoje: está detrás de Quriate-Jearim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 13, 'E passando dali ao monte de Efraim, vieram até a casa de Mica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 14, 'Então aqueles cinco homens que haviam ido a reconhecer a terra de Laís, disseram a seus irmãos: Não sabeis como em estas casas há éfode e ídolos, e imagem de escultura e de fundição? Olhai pois o que haveis de fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 15, 'E achegando-se ali, vieram à casa do jovem levita em casa de Mica, e perguntaram-lhe como estava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 16, 'E os seiscentos homens, que eram dos filhos de Dã, estavam armados de suas armas de guerra à entrada da porta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 17, 'E subindo os cinco homens que haviam ido a reconhecer a terra, entraram ali, e tomaram a imagem de escultura, e o éfode, e os ídolos, e a imagem de fundição, enquanto o sacerdote estava à entrada da porta com os seiscentos homens armados'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 18, 'Entrando, pois, aqueles na casa de Mica, tomaram a imagem de escultura, o éfode, e os ídolos, e a imagem de fundição. E o sacerdote lhes disse: Que fazeis vós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 19, 'E eles lhe responderam: Cala, põe a mão sobre tua boca, e vem conosco, para que sejas nosso pai e sacerdote. É melhor que tu sejas sacerdote em casa de um homem só, que de uma tribo e família de Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 20, 'E alegrou-se o coração do sacerdote; o qual tomando o éfode e os ídolos, e a imagem, veio entre a gente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 21, 'E eles voltaram e foram-se; e puseram os meninos, e o gado e a bagagem, diante de si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 22, 'E quando já se haviam afastado da casa de Mica, os homens que habitavam nas casas vizinhas à casa de Mica, se juntaram, e seguiram aos filhos de Dã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 23, 'E gritando aos de Dã, estes viraram seus rostos, e disseram a Mica: Que tens que juntaste gente?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 24, 'E ele respondeu: Meus deuses que eu fiz, que levais juntamente com o sacerdote, e vos vades: que mais me resta? E a que propósito me dizeis: Que tens?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 25, 'E os filhos de Dã lhe disseram: Não grites atrás de nós, não seja que os de ânimo impetuoso vos acometam, e percas também tua vida, e a vida dos teus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 26, 'E indo os filhos de Dã seu caminho, e vendo Mica que eram mais fortes que ele, voltou-se e regressou à sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 27, 'E eles levando as coisas que havia feito Mica, juntamente com o sacerdote que tinha, chegaram a Laís, ao povo tranquilo e seguro; e meteram-nos à espada, e abrasaram a cidade com fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 28, 'E não houve quem os defendesse, porque estavam longe de Sidom, e não tinham comércio com ninguém. E a cidade estava no vale que há em Bete-Reobe. Logo reedificaram a cidade, e habitaram nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 29, 'E chamaram o nome daquela cidade Dã, conforme ao nome de Dã seu pai, filho de Israel, bem que antes se chamava a cidade Laís.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 30, 'E os filhos de Dã levantaram para si imagem de escultura; e Jônatas, filho de Gérson, filho de Manassés, ele e seus filhos foram sacerdotes na tribo de Dã, até o dia do cativeiro desta terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 18, 31, 'E levantaram para si a imagem de Mica, a qual ele havia feito, todo aquele tempo que a casa de Deus esteve em Siló.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 1, 'Naqueles dias, quando não havia rei em Israel, houve um levita que morava como peregrino nos lados do monte de Efraim, o qual se havia tomado mulher concubina de Belém de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 2, 'E sua concubina adulterou contra ele, e foi-se dele à casa de seu pai, a Belém de Judá, e esteve ali por tempo de quatro meses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 3, 'E levantou-se seu marido, e seguiu-a, para falar-lhe amorosamente e trazê-la de volta, levando consigo um criado seu e um par de asnos; e ela o meteu na casa de seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 4, 'E vendo-lhe o pai da moça, saiu-lhe a receber contente; e seu sogro, pai da moça, o deteve, e ficou em sua casa três dias, comendo e bebendo, e repousando ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 5, 'E ao quarto dia, quando se levantaram de manhã, levantou-se também o levita para ir-se, e o pai da moça disse a seu genro: Conforta teu coração com um bocado de pão, e depois vos ireis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 6, 'E sentaram-se eles dois juntos, e comeram e beberam. E o pai da moça disse ao homem: Eu te rogo que te queiras ficar aqui esta noite, e teu coração se alegrará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 7, 'E levantando-se o homem para ir-se, o sogro lhe constrangeu a que voltasse e tivesse ali a noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 8, 'E ao quinto dia levantando-se de manhã para ir-se, disse-lhe o pai da moça: Conforta agora teu coração. E havendo comido ambos a dois, detiveram-se até que já declinava o dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 9, 'Levantou-se logo o homem para ir-se, ele, e sua concubina, e seu criado. Então seu sogro, o pai da moça, lhe disse: Eis que o dia declina para se pôr o sol, rogo-te que vos estejais aqui a noite; eis que o dia se acaba, passa aqui a noite, para que se alegre teu coração; e amanhã vos levantareis cedo a vosso caminho, e chegarás a tuas tendas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 10, 'Mas o homem não quis ficar ali a noite, mas sim que se levantou e partiu, e chegou até em frente de Jebus, que é Jerusalém, com seu par de asnos preparados, e com sua concubina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 11, 'E estando já junto a Jebus, o dia havia declinado muito: e disse o criado a seu senhor: Vem agora, e vamo-nos a esta cidade dos jebuseus, para que tenhamos nela a noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 12, 'E seu senhor lhe respondeu: Não iremos a nenhuma cidade de estrangeiros, que não seja dos filhos de Israel: antes passaremos até Gibeá. E disse a seu criado:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 13, 'Vem, cheguemos a um desses lugares, para ter a noite em Gibeá, ou em Ramá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 14, 'Passando pois, caminharam, e o sol se pôs junto a Gibeá, que era de Benjamim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 15, 'E apartaram-se do caminho para entrar a ter ali a noite em Gibeá; e entrando, sentaram-se na praça da cidade, porque não houve quem os acolhesse em casa para passar a noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 16, 'E eis que um homem velho, que à tarde vinha do campo de trabalhar; o qual era do monte de Efraim, e morava como peregrino em Gibeá, mas os moradores daquele lugar eram filhos de Benjamim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 17, 'E levantando o velho os olhos, viu aquele viajante na praça da cidade, e disse-lhe: Para onde vais, e de onde vens?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 18, 'E ele respondeu: Passamos de Belém de Judá aos lados do monte de Efraim, de onde eu sou; e parti até Belém de Judá; e vou à casa do SENHOR, e não há quem me receba em casa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 19, 'Ainda que nós tenhamos palha e de comer para nossos asnos, e também temos pão e vinho para mim e para tua serva, e para o criado que está com teu servo; de nada temos falta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 20, 'E o homem velho disse: Paz seja contigo; tua necessidade toda seja somente a meu cargo, contanto que não passes a noite na praça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 21, 'E metendo-os em sua casa, deu de comer a seus asnos; e eles se lavaram os pés, e comeram e beberam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 22, 'E quando estavam jubilosos, eis que os homens daquela cidade, homens malignos, cercam a casa, e batiam as portas, dizendo ao homem velho dono da casa: Tira fora o homem que entrou em tua casa, para que o conheçamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 23, 'E saindo a eles aquele homem, amo da casa, disse-lhes: Não, irmãos meus, rogo-vos que não cometais este mal, pois que este homem entrou em minha casa, não façais esta maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 24, 'Eis aqui minha filha virgem, e a concubina dele: eu as tirarei agora para vós; humilhai-as, e fazei com elas como vos parecer, e não façais a este homem coisa tão infame.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 25, 'Mas aqueles homens não lhe quiseram ouvir; pelo que tomando aquele homem sua concubina, tirou-a fora: e eles a conheceram, e abusaram dela toda a noite até a manhã, e deixaram-na quando apontava a alva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 26, 'E já que amanhecia, a mulher veio, e caiu diante da porta da casa daquele homem onde seu senhor estava, até que foi de dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 27, 'E levantando-se de manhã seu senhor, abriu as portas da casa, e saiu para ir seu caminho, e eis que, a mulher sua concubina estava estendida diante da porta da casa, com as mãos sobre o umbral.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 28, 'E ele lhe disse: Levanta-te, e vamo-nos. Mas ela não respondeu. Então a levantou o homem, e lançando-a sobre seu asno, levantou-se e foi-se a seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 29, 'E em chegando à sua casa, toma uma espada, pegou sua concubina, e despedaçou-a com seus ossos em doze partes, e enviou-as por todos os termos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 19, 30, 'E todo aquele que o via, dizia: Jamais se fez nem visto tal coisa, desde o tempo que os filhos de Israel subiram da terra do Egito até hoje. Considerai isto, dai conselho, e falai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 1, 'Então saíram todos os filhos de Israel, e reuniu-se a congregação como um só homem, desde Dã até Berseba e a terra de Gileade, ao SENHOR em Mispá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 2, 'E os principais de todo aquele povo, de todas as tribos de Israel, se acharam presentes na reunião do povo de Deus, quatrocentos mil homens a pé que tiravam espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 3, 'E os filhos de Benjamim ouviram que os filhos de Israel haviam subido a Mispá. E disseram os filhos de Israel: Dizei como foi esta maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 4, 'Então o homem levita, marido da mulher morta, respondeu e disse: Eu cheguei a Gibeá de Benjamim com minha concubina, para ter ali a noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 5, 'E levantando-se contra mim os de Gibeá, cercaram sobre mim a casa de noite, com ideia de matar-me, e oprimiram minha concubina de tal maneira, que ela foi morta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 6, 'Então tomando eu minha concubina, cortei-a em peças, e enviei-as por todo aquele termo da possessão de Israel: porquanto fizeram maldade e crime em Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 7, 'Eis que todos vós os filhos de Israel estais presentes; dai-vos aqui parecer e conselho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 8, 'Então todo aquele povo, como um só homem, se levantou, e disseram: Nenhum de nós irá à sua tenda, nem nos apartaremos cada um à sua casa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 9, 'Até que façamos isto sobre Gibeá: que lancemos sortes contra ela;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 10, 'E tomaremos dez homens de cada cem por todas as tribos de Israel, e de cada mil cem, e mil de cada dez mil, que levem mantimento para o povo que deve agir, indo contra Gibeá de Benjamim, conforme toda a abominação que havia cometido em Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 11, 'E juntaram-se todos os homens de Israel contra a cidade, ligados como um só homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 12, 'E as tribos de Israel enviaram homens por toda a tribo de Benjamim, dizendo: Que maldade é esta que foi feita entre vós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 13, 'Entregai, pois, agora aqueles homens, malignos, que estão em Gibeá, para que os matemos, e varramos o mal de Israel. Mas os de Benjamim não quiseram ouvir a voz de seus irmãos os filhos de Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 14, 'Antes os de Benjamim se juntaram das cidades de Gibeá, para sair a lutar contra os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 15, 'E foram contados naquele tempo os filhos de Benjamim das cidades, vinte e seis mil homens que tiravam espada, sem os que moravam em Gibeá, que foram por conta setecentos homens escolhidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 16, 'De toda aquela gente havia setecentos homens escolhidos, que eram canhotos, todos os quais atiravam uma pedra com a funda a um fio de cabelo, e não erravam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 17, 'E foram contados os homens de Israel, fora de Benjamim, quatrocentos mil homens que tiravam espada, todos estes homens de guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 18, 'Levantaram-se logo os filhos de Israel, e subiram à casa de Deus, e consultaram a Deus, dizendo: Quem subirá de nós o primeiro na guerra contra os filhos de Benjamim? E o SENHOR respondeu: Judá o primeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 19, 'Levantando-se, pois, de manhã os filhos de Israel, puseram acampamento contra Gibeá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 20, 'E saíram os filhos de Israel a combater contra Benjamim; e os homens de Israel ordenaram a batalha contra eles junto a Gibeá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 21, 'Saindo então de Gibeá os filhos de Benjamim, derrubaram em terra aquele dia vinte e dois mil homens dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 22, 'Mas reanimando-se o povo, os homens de Israel voltaram a ordenar a batalha no mesmo lugar onde a haviam ordenado o primeiro dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 23, 'Porque os filhos de Israel subiram, e choraram diante do SENHOR até à tarde, e consultaram com o SENHOR, dizendo: Voltarei a lutar com os filhos de Benjamim meu irmão? E o SENHOR lhes respondeu: Subi contra ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 24, 'Então os filhos de Israel se aproximaram no dia seguinte contra os filhos de Benjamim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 25, 'E aquele segundo dia, saindo Benjamim de Gibeá contra eles, derrubaram por terra outros dezoito mil homens dos filhos de Israel, todos os quais tiravam espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 26, 'Então subiram todos os filhos de Israel, e todo aquele povo, e vieram à casa de Deus; e choraram, e sentaram-se ali diante do SENHOR, e jejuaram naquele dia até à tarde; e sacrificaram holocaustos e pacíficos diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 27, 'E os filhos de Israel perguntaram ao SENHOR, (porque a arca do pacto de Deus estava ali naqueles dias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 28, 'E Fineias, filho de Eleazar, filho de Arão, se apresentava diante dela naqueles dias,) e disseram: Voltarei a sair em batalha contra os filhos de Benjamim meu irmão, ou ficarei quieto? E o SENHOR disse: Subi, que amanhã eu o entregarei em tua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 29, 'E pôs Israel emboscadas ao redor de Gibeá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 30, 'Subindo então os filhos de Israel contra os filhos de Benjamim o terceiro dia, ordenaram a batalha diante de Gibeá, como as outras vezes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 31, 'E saindo os filhos de Benjamim contra o povo, afastados que foram da cidade, começaram a ferir alguns do povo, matando como das outras vezes pelos caminhos, um dos quais sobe a Betel, e o outro a Gibeá no acampamento: e mataram uns trinta homens de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 32, 'E os filhos de Benjamim diziam: Derrotados são diante de nós, como antes. Mas os filhos de Israel diziam: Fugiremos, e os afastaremos da cidade até os caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 33, 'Então, levantando-se todos os de Israel de seu lugar, puseram-se em ordem em Baal-Tamar: e também as emboscadas de Israel saíram de seu lugar, do prado de Gibeá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 34, 'E vieram contra Gibeá dez mil homens escolhidos de todo Israel, e a batalha começou a agravar-se: mas eles não sabiam que o mal se aproximava sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 35, 'E feriu o SENHOR a Benjamim diante de Israel; e mataram os filhos de Israel aquele dia vinte e cinco mil e cem homens de Benjamim, todos os quais tiravam espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 36, 'E viram os filhos de Benjamim que eram mortos; pois os filhos de Israel haviam dado lugar a Benjamim, porque estavam confiantes nas emboscadas que haviam posto detrás de Gibeá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 37, 'Então as emboscadas atacaram prontamente Gibeá, e se estenderam, e passaram à espada toda a cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 38, 'Já os israelitas estavam combinados com as emboscadas, que fizessem muito fogo, para que subisse grande fumaça da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 39, 'Logo, pois, que os de Israel se viraram na batalha, os de Benjamim começaram a derrubar feridos de Israel uns trinta homens, e já diziam: Certamente eles caíram diante de nós, como na primeira batalha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 40, 'Mas quando a chama começou a subir da cidade, uma coluna de fumaça, Benjamim virou a olhar atrás; e eis que o fogo da cidade subia ao céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 41, 'Então deram meia-volta os homens de Israel, e os de Benjamim se encheram de temor: porque viram que o mal havia vindo sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 42, 'Voltaram-se, pois, de costas diante de Israel até o caminho do deserto; mas o esquadrão os alcançou, e os saídos da cidade os matavam, depois de virem ao meio deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 43, 'Assim cercaram aos de Benjamim, e os perseguiram e pisaram, desde Menuá até em frente de Gibeá até o oriente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 44, 'E caíram de Benjamim dezoito mil homens, todos eles homens de guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 45, 'Voltando-se logo, fugiram até o deserto, à penha de Rimom, e deles exterminaram cinco mil homens nos caminhos: foram ainda perseguindo-os até Gidom, e mataram deles dois mil homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 46, 'Assim todos os que de Benjamim morreram aquele dia, foram vinte e cinco mil homens que tiravam espada, todos eles homens de guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 47, 'Porém se voltaram e fugiram ao deserto à penha de Rimom seiscentos homens, os quais estiveram na penha de Rimom quatro meses:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 20, 48, 'E os homens de Israel voltaram aos filhos de Benjamim, e passaram-nos à espada, a homens e animais na cidade, e tudo o que foi achado: também puseram fogo a todas as cidades que achavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 1, 'E os homens de Israel haviam jurado em Mispá, dizendo: Nenhum de nós dará sua filha aos de Benjamim por mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 2, 'E veio o povo à casa de Deus, e estiveram ali até à tarde diante de Deus; e levantando sua voz fizeram grande pranto, e disseram:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 3, 'Ó SENHOR Deus de Israel, por que sucedeu isto em Israel, que falte hoje de Israel uma tribo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 4, 'E ao dia seguinte o povo se levantou de manhã, e edificaram ali altar, e ofereceram holocaustos e pacíficos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 5, 'E disseram os filhos de Israel: Quem de todas as tribos de Israel não subiu à reunião próximo do SENHOR? Porque se havia feito grande juramento contra o que não subisse ao SENHOR em Mispá, dizendo: Sofrerá morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 6, 'E os filhos de Israel se arrependeram por causa de Benjamim seu irmão, e disseram: Uma tribo é hoje cortada de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 7, 'Que faremos em quanto a mulheres para os que restaram? Nós juramos pelo SENHOR que não lhes temos de dar nossas filhas por mulheres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 8, 'E disseram: Há alguém das tribos de Israel que não tenha subido ao SENHOR em Mispá? E acharam que ninguém de Jabes-Gileade havia vindo ao acampamento à reunião:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 9, 'Porque o povo foi contado, e não havia ali homem dos moradores de Jabes-Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 10, 'Então a congregação enviou ali doze mil homens dos mais valentes, e mandaram-lhes, dizendo: Ide e ponde à espada aos moradores de Jabes-Gileade, e as mulheres e meninos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 11, 'Mas fareis desta maneira: matareis a todo homem e a toda mulher que tiver se deitado com homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 12, 'E acharam dos moradores de Jabes-Gileade quatrocentas virgens que não tinham se deitado com homem, e trouxeram-nas ao acampamento em Siló, que está na terra de Canaã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 13, 'Toda a congregação enviou logo a falar aos filhos de Benjamim que estavam na penha de Rimom, e chamaram-nos em paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 14, 'E voltaram então os de Benjamim; e deram-lhes por mulheres as que haviam escravo vivas das mulheres de Jabes-Gileade: mas não lhes bastaram estas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 15, 'E o povo teve dor por causa de Benjamim, de que o SENHOR houvesse feito brecha nas tribos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 16, 'Então os anciãos da congregação disseram: Que faremos acerca de mulheres para os que restaram? Porque as mulheres tinham sido exterminadas de Benjamim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 17, 'E disseram: A herança dos que escaparam será o que era de Benjamim, para que não seja uma tribo extinta de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 18, 'Nós porém, não lhes podemos dar mulheres de nossas filhas, porque os filhos de Israel juraram, dizendo: Maldito o que der mulher a Benjamim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 19, 'Agora bem, disseram, eis que cada ano há solenidade do SENHOR em Siló, que está ao norte de Betel, e ao lado oriental do caminho que sobe de Betel a Siquém, e ao sul de Lebona.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 20, 'E mandaram aos filhos de Benjamim, dizendo: Ide, e ponde emboscadas nas vinhas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 21, 'E estai atentos: e quando virdes sair as filhas de Siló a dançar em cirandas, vós saireis das vinhas, e arrebatareis cada um mulher para si das filhas de Siló, e vos ireis à terra de Benjamim:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 22, 'E quando vierem os pais delas ou seus irmãos a nos exigirem, nós lhes diremos: Tende piedade de nós em lugar deles: pois que nós na guerra não tomamos mulheres para todos: que vós não as destes a eles, para que agora sejais culpáveis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 23, 'E os filhos de Benjamim o fizeram assim; pois tomaram mulheres conforme seu número, tomando das que dançavam; e indo logo, voltaram-se à sua herança, e reedificaram as cidades, e habitaram nelas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 24, 'Então os filhos de Israel se foram também dali, cada um à sua tribo e à sua família, saindo dali cada um à sua propriedade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 7, 'Juízes', 'Jz', 21, 25, 'Nestes dias não havia rei em Israel; cada um fazia o que era correto diante de seus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 1, 'E aconteceu nos dias que governavam os juízes, que houve fome na terra. E um homem de Belém de Judá, foi a peregrinar nos campos de Moabe, ele e sua mulher, e dois filhos seus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 2, 'O nome daquele homem era Elimeleque, e o de sua mulher Noemi; e os nomes de seus dois filhos eram Malom e Quiliom, efrateus de Belém de Judá. Chegaram, pois, aos campos de Moabe, e assentaram ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 3, 'E morreu Elimeleque, marido de Noemi, e restou ela com seus dois filhos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 4, 'Os quais tomaram para si mulheres de Moabe, o nome da uma Orfa, e o nome da outra Rute; e habitaram ali uns dez anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 5, 'E morreram também os dois, Malom e Quiliom, restando assim a mulher desamparada de seus dois filhos e de seu marido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 6, 'Então se levantou com suas noras, e voltou-se dos campos de Moabe: porque ouviu no campo de Moabe que o SENHOR havia visitado a seu povo para dar-lhes pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 7, 'Saiu, pois, do lugar de onde havia estado, e com ela suas duas noras, e começaram em caminhar para voltar-se à terra de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 8, 'E Noemi disse a suas duas noras: Andai, voltai-vos cada uma à casa de sua mãe: o SENHOR faça convosco misericórdia, como a fizestes com os mortos e comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 9, 'Dê-vos o SENHOR que acheis descanso, cada uma em casa de seu marido: beijou-as logo, e elas choraram a voz em grito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 10, 'E disseram-lhe: Certamente nós voltaremos contigo a teu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 11, 'E Noemi respondeu: Voltai, filhas minhas; para que ireis comigo? Tenho eu mais filhos no ventre, que possam ser vossos maridos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 12, 'Voltai, filhas minhas, e ide; que eu já sou velha para ser para me casar com homem. E ainda que dissesse: Tenho esperança; e esta noite me casasse com um homem, e ainda desse à luz filhos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 13, 'Teríeis vós de esperá-los até que fossem grandes? Ficaríeis vós sem se casar por causa deles? Não, filhas minhas; que maior amargura tenho eu que vós, pois a mão do SENHOR saiu contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 14, 'Mas elas levantando outra vez sua voz, choraram: e Orfa beijou à sua sogra, mas Rute se ficou com ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 15, 'E Noemi disse: Eis que tua cunhada se voltou a seu povo e a seus deuses; volta-te atrás dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 16, 'E Rute respondeu: Não me rogues que te deixe, e que me aparte de ti: porque de onde quer que tu fores, irei eu; e de onde quer que viveres, viverei. Teu povo será meu povo, e teu Deus meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 17, 'Onde tu morreres, morrerei eu, e ali serei sepultada: assim me faça o SENHOR, e assim me dê, que somente a morte fará separação entre mim e ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 18, 'E vendo Noemi que estava tão decidida a ir com ela, deixou de falar-lhe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 19, 'Andaram, pois, elas duas até que chegaram a Belém: e aconteceu que entrando em Belém, toda a cidade se comoveu por razão delas, e diziam: Não é esta Noemi?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 20, 'E ela lhes respondia: Não me chameis Noemi, mas sim me chamai Mara: porque em grande amargura me pôs o Todo-Poderoso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 21, 'Eu me fui cheia, mas vazia me fez voltar o SENHOR. Por que me chamareis Noemi, já que o SENHOR deu testemunho contra mim, e o Todo-Poderoso me afligiu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 1, 22, 'Assim voltou Noemi e Rute moabita sua nora com ela; voltou dos campos de Moabe, e chegaram a Belém no princípio da colheita das cevadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 1, 'E tinha Noemi um parente de seu marido, homem poderoso e rico, da família de Elimeleque, o qual se chamava Boaz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 2, 'E Rute a moabita disse a Noemi: Rogo-te que me deixes ir ao campo, e colherei espigas atrás daquele a cujos olhos achar favor. E ela lhe respondeu: Vai, filha minha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 3, 'Foi, pois, e chegando, tirou espigas no campo atrás dos ceifeiros: e aconteceu porventura, que o terreno era de Boaz, o qual era da parentela de Elimeleque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 4, 'E eis que Boaz veio de Belém, e disse aos ceifeiros: O SENHOR seja convosco. E eles responderam: O SENHOR te abençoe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 5, 'E Boaz disse a seu criado o supervisor dos ceifeiros: De quem é esta moça?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 6, 'E o criado, supervisor dos ceifeiros, respondeu e disse: É a moça de Moabe, que voltou com Noemi dos campos de Moabe;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 7, 'E disse: Rogo-te que me deixes colher e juntar atrás dos ceifeiros entre os feixes; entrou, pois, e está desde pela manhã até agora, menos um pouco que se deteve em casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 8, 'Então Boaz disse á Rute: Ouve, filha minha, não vás a tirar espigas em outro campo, nem passes daqui: e aqui estarás com minhas moças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 9, 'Olha bem o campo que colherem, e segue-as: porque eu mandei aos moços que não te toquem. E se tiveres sede, vai aos vasos, e bebe da água que os moços tirarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 10, 'Ela então baixando seu rosto inclinou-se à terra, e disse-lhe: Por que achei favor em teus olhos para que tu me reconheças, sendo eu estrangeira?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 11, 'E respondendo Boaz, disse-lhe: Por certo se me declarou tudo o que fizeste com tua sogra depois da morte de teu marido, e que deixando teu pai e tua mãe e a terra de onde nasceste, vieste a um povo que não conheceste antes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 12, 'O SENHOR recompense tua obra, e tua remuneração seja cheia pelo SENHOR Deus de Israel, que vieste para cobrir-te debaixo de suas asas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 13, 'E ela disse: Senhor meu, ache eu favor diante de teus olhos; porque me consolaste, e porque falaste ao coração de tua serva, não sendo eu como uma de tuas criadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 14, 'E Boaz lhe disse à hora de comer: Achega-te aqui, e come do pão, e molha teu bocado no vinagre. E sentou-se ela junto aos ceifeiros, e ele lhe deu grãos tostados, e comeu até que se fartou e lhe sobrou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 15, 'Levantou-se logo para tirar espigas. E Boaz mandou a seus criados, dizendo: Colha também espigas entre os feixes, e não a envergonheis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 16, 'Antes lançareis de propósito dos feixes, e a deixareis que colha, e não a repreendais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 17, 'E tirou espigas no campo até à tarde, e debulhou o que havia colhido, e foi como um efa de cevada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 18, 'E tomou-o, e veio à cidade; e sua sogra viu o que havia colhido. Tirou também logo o que lhe havia sobrado depois de farta, e deu-lhe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 19, 'E disse-lhe sua sogra: Onde tiraste espigas hoje? e onde trabalhaste? Bendito seja o que te reconheceu. E ela declarou à sua sogra o que lhe havia acontecido com aquele, e disse: O nome do homem com quem hoje trabalhei é Boaz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 20, 'E disse Noemi à sua nora: Seja ele bendito do SENHOR, pois que não recusou aos vivos a benevolência que teve para com os finados. Disse-lhe depois Noemi: Nosso parente é aquele homem, e de nossos remidores é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 21, 'E Rute moabita disse: a mais disto me disse: Junta-te com meus criados, até que tenham acabado toda minha colheita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 22, 'E Noemi respondeu a Rute sua nora: Melhor é, filha minha, que saias com suas criadas, que não que te encontrem em outro campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 2, 23, 'Esteve, pois, junto com as moças de Boaz tirando espigas, até que a colheita das cevadas e a dos trigos foi acabada; mas com sua sogra habitou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 3, 1, 'E disse-lhe sua sogra Noemi: Filha minha, não tenho de buscar descanso a ti, para que fiques bem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 3, 2, 'Não é Boaz nosso parente, com cujas moças tu tens estado? Eis que ele aventa esta noite a os grãos de cevada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 3, 3, 'Tu te lavarás, pois, e te ungirás, e vestindo-te tuas vestes, passarás à eira; mas não te darás a conhecer ao homem até que ele tenha acabado de comer e de beber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 3, 4, 'E quando ele se deitar, repara tu o lugar de onde ele se deitará, e irás, e descobrirás os pés, e te deitarás ali; e ele te dirá o que tenhas de fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 3, 5, 'E lhe respondeu: Farei tudo o que tu me mandares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 3, 6, 'Desceu, pois à eira, e fez tudo o que sua sogra lhe havia mandado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 3, 7, 'E quando Boaz havia comido e bebido, e seu coração esteve contente, retirou-se para dormir a um lado do amontoado. Então ela veio caladamente, e revelou os pés, e deitou-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 3, 8, 'E aconteceu, que à meia noite se estremeceu aquele homem, e apalpou: e eis que, a mulher que estava deitada a seus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 3, 9, 'Então ele disse: Quem és? E ela respondeu: Eu sou Rute tua serva: estende a borda de tua capa sobre tua serva, porquanto és parente próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 3, 10, 'E ele disse: Bendita sejas tu do SENHOR, filha minha; que fizeste melhor tua última bondade que a primeira, não indo atrás dos rapazes, sejam pobres ou ricos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 3, 11, 'Agora, pois, não temas, filha minha: eu farei contigo o que tu disseres, pois que toda a porta de meu povo sabe que és mulher virtuosa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 3, 12, 'E agora, ainda que seja certo que eu sou parente próximo, contudo isso há parente mais próximo que eu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 3, 13, 'Repousa esta noite, e quando for de dia, se ele te redimir, bem, redima-te; mas se ele não te quiser redimir, eu te redimirei, vive o SENHOR. Descansa, pois, até a manhã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 3, 14, 'E depois que repousou a seus pés até a manhã, levantou-se, antes que ninguém pudesse conhecer a outro. E ele disse: Não se saiba que tenha vindo mulher à eira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 3, 15, 'Depois lhe disse: Aproxima o lenço que trazes sobre ti, e segura-o. E enquanto ela o segurava, ele mediu seis medidas de cevada, e as pôs às costas: e veio ela à cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 3, 16, 'Assim que veio à sua sogra, esta lhe disse: Que houve, minha filha? E ela lhe declarou ela tudo o que com aquele homem lhe havia acontecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 3, 17, 'E disse: Estas seis medidas de cevada me deu, dizendo-me: Porque não vás vazia à tua sogra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 3, 18, 'Então Noemi disse: Repousa, filha minha, até que saibas como a coisa se sucede; porque aquele homem não parará até que hoje conclua o negócio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 1, 'E Boaz subiu à porta da cidade e sentou-se ali: e eis que passava aquele parente do qual havia Boaz falado, e disse-lhe: Ei, fulano, vem aqui e senta-te. E ele veio, e sentou-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 2, 'Então ele tomou dez homens dos anciãos da cidade, e disse: Sentai-vos aqui. E eles se sentaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 3, 'Logo disse ao parente: Noemi, que voltou do campo de Moabe, vende uma parte das terras que teve nosso irmão Elimeleque;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 4, 'E eu decidi fazê-lo saber a ti, e dizer-te que a tomes diante dos que estão aqui sentados, e diante dos anciãos de meu povo. Se houveres de redimir, redime; e se não quiseres redimir, declara-o a mim para que eu o saiba: porque não há outro que redima a não ser tu, e eu depois de ti. E ele respondeu: Eu redimirei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 5, 'Então replicou Boaz: O mesmo dia que tomares as terras da mão de Noemi, hás de tomar também a Rute moabita, mulher do defunto, para que suscites o nome do morto sobre sua possessão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 6, 'E respondeu o parente: Não posso redimir por minha parte, porque lançaria a perder minha propriedade: redime tu usando de meu direito, porque eu não poderei redimir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 7, 'Havia já de longo tempo este costume em Israel na remissão ou contrato, que para a confirmação de qualquer negócio, o um se tirava o sapato e o dava a seu companheiro: e este era o testemunho em Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 8, 'Então o parente disse a Boaz: Toma-o tu. E descalçou seu sapato.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 9, 'E Boaz disse aos anciãos e a todo aquele povo: Vós sois hoje testemunhas de que tomo todas as coisas que foram de Elimeleque, e tudo o que foi de Quiliom e de Malom, da mão de Noemi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 10, 'E que também tomo por minha mulher a Rute moabita, mulher de Malom, para suscitar o nome do defunto sobre sua herança, para que o nome do morto não se apague dentre seus irmãos e da porta de seu lugar. Vós sois hoje testemunhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 11, 'E disseram todos os do povo que estavam à porta com os anciãos: Testemunhas somos. O SENHOR faça à mulher que entra em tua casa como a Raquel e a Lia, as quais duas edificaram a casa de Israel; e tu sejas ilustre em Efrata, e tenhas renome em Belém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 12, 'E da semente que o SENHOR te der desta moça, seja tua casa como a casa de Perez, o que Tamar deu a Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 13, 'Então Boaz tomou a Rute, e ela foi sua mulher; e logo que entrou a ela, o SENHOR lhe deu que concebesse e desse à luz um filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 14, 'E as mulheres diziam a Noemi: Louvado seja o SENHOR, que fez que não te faltasse hoje parente, cujo nome será nomeado em Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 15, 'O qual será restaurador de tua alma, e o que sustentará tua velhice; pois que tua nora, a qual te ama e te vale mais que sete filhos, o fez nascer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 16, 'E tomando Noemi o filho, o pôs em seu colo, e foi-lhe sua ama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 17, 'E as vizinhas dizendo, a Noemi nasceu um filho, lhe puseram nome; e chamaram-lhe Obede. Este é pai de Jessé, pai de Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 18, 'E estas são as gerações de Perez: Perez gerou a Hezrom;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 19, 'E Hezrom gerou a Rão, e Rão gerou a Aminadabe;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 20, 'E Aminadabe gerou a Naassom, e Naassom gerou a Salmom;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 21, 'E Salmom gerou a Boaz, e Boaz gerou a Obede;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 8, 'Rute', 'Rt', 4, 22, 'E Obede gerou a Jessé, e Jessé gerou a Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 1, 'Houve um homem de Ramataim de Zofim, do monte de Efraim, que se chamava Elcana, filho de Jeroão, filho de Eliú, filho de Toú, filho de Zufe, efraimita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 2, 'E tinha ele duas mulheres; o nome da uma era Ana, e o nome da outra Penina. E Penina tinha filhos, mas Ana não os tinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 3, 'E esse homem subia todos os anos de sua cidade, para adorar e sacrificar ao SENHOR dos exércitos em Siló. E ali estavam os dois filhos de Eli, Hofni e Fineias, sacerdotes do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 4, 'E quando vinha o dia, Elcana sacrificava, e dava à sua mulher Penina, e a todos os seus filhos e a todas as suas filhas, a cada um a sua porção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 5, 'Mas a Ana ele dava uma porção selecionada; porque amava a Ana, ainda que o SENHOR houvesse fechado sua madre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 6, 'E sua concorrente a irritava, irando-a e entristecendo-a, porque o SENHOR havia fechado sua madre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 7, 'E assim fazia cada ano: quando subia à casa do SENHOR, irritava assim à outra; pelo qual ela chorava, e não comia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 8, 'E Elcana seu marido lhe disse: Ana, por que choras? Por que não comes? E por que está afligido teu coração? Não te sou eu melhor que dez filhos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 9, 'E levantou-se Ana depois que havia comido e bebido em Siló; e enquanto o sacerdote Eli estava sentado em uma cadeira junto a um pilar do templo do SENHOR,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 10, 'Ela com amargura de alma orou ao SENHOR, e chorou abundantemente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 11, 'E fez um voto, dizendo: “SENHOR dos exércitos, se olhares a aflição da tua serva, e te lembrares de mim, e não te esqueceres da tua serva, mas deres à tua serva um filho homem, eu o dedicarei ao SENHOR todos os dias da sua vida, e não subirá navalha sobre sua cabeça”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 12, 'E sucedeu que, enquanto ela continuava a orar diante do SENHOR, Eli observava a sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 13, 'Mas Ana falava em seu coração, e somente se moviam seus lábios, e sua voz não se ouvia; e pensava Eli que ela estava embriagada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 14, 'Então, disse-lhe Eli: “Até quando estarás embriagada? Afasta-te do vinho”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 15, 'E Ana lhe respondeu: Não, meu senhor; eu sou uma mulher sofredora de espírito. Não bebi vinho nem bebida forte, mas tenho derramado minha alma diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 16, 'Não consideres a tua serva como mulher ímpia, porque é da grandeza das minhas angústias e da minha aflição que tenho falado até agora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 17, 'E Eli respondeu: “Vai em paz, e o Deus de Israel te conceda o pedido que lhe fizeste”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 18, 'E ela disse: “Que a tua serva ache favor diante de teus olhos”. E a mulher se foi seu caminho, e comeu, e não esteve mais triste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 19, 'E levantando-se de manhã, adoraram diante do SENHOR, e voltaram, e vieram a sua casa em Ramá. E Elcana se deitou com sua mulher Ana, e o SENHOR se lembrou dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 20, 'E sucedeu que, corrido o tempo, depois de Ana haver concebido, deu à luz um filho, e pôs-lhe o nome de Samuel, dizendo: “Pois eu o pedi ao SENHOR”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 21, 'Depois subiu o homem Elcana, com toda sua família, a sacrificar ao SENHOR o sacrifício costumeiro, e seu voto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 22, 'Mas Ana não subiu, mas sim disse a seu marido: Eu não subirei até que o menino seja desmamado; para que o leve e seja apresentado diante do SENHOR, e fique ali para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 23, 'E Elcana seu marido lhe respondeu: Faze o que bem te parecer; fica-te até que o desmames; somente o SENHOR cumpra sua palavra. E ficou a mulher, e creu seu filho até que o desmamou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 24, 'E depois que o desmamou, levou-o consigo, com três bezerros, e um efa de farinha, e uma vasilha de vinho, e trouxe-o à casa do SENHOR em Siló: e o menino era pequeno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 25, 'E matando o bezerro, trouxeram o menino a Eli.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 26, 'E ela disse: Oh, senhor meu! Vive tua alma, senhor meu, eu sou aquela mulher que esteve aqui junto a ti orando ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 27, 'Por este menino orava, e o SENHOR me deu o que lhe pedi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 1, 28, 'Eu, pois, o devolvo também ao SENHOR: todos os dias que viver, será do SENHOR. E adorou ali ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 1, 'E Ana orou e disse: Meu coração se regozija no SENHOR, Meu poder é exaltado no SENHOR; Minha boca fala triunfante sobre meus inimigos, Porquanto me alegrei em tua salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 2, 'Não há santo como o SENHOR: Porque não há ninguém além de ti; E não há refúgio como o nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 3, 'Não faleis tantas coisas soberbas; Cessem as palavras arrogantes de vossa boca; Porque o Deus de todo conhecimento é o SENHOR, E a ele cabe pesar as ações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 4, 'Os arcos dos fortes foram quebrados, E os fracos se cingiram de força.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 5, 'Os fartos se alugaram por pão: E cessaram os famintos; até a estéril deu à luz sete, e a que tinha muitos filhos se enfraqueceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 6, 'O SENHOR mata e dá vida; ele faz descer ao Xeol, e faz [de lá] subir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 7, 'O SENHOR empobrece e enriquece; abate e exalta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 8, 'Ele levanta do pó ao pobre, e ao necessitado ergue do esterco, para assentá-lo com os príncipes; e faz que tenham por propriedade assento de honra; porque do SENHOR são os alicerces da terra, e assentou o mundo sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 9, 'Ele guarda os pés de seus santos, Mas os ímpios perecem em trevas; Porque ninguém será forte por sua força.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 10, 'Diante do SENHOR serão quebrantados seus adversários, E sobre eles trovejará desde os céus: o SENHOR julgará os termos da terra, E dará força a seu Rei, E exaltará o poder de seu ungido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 11, 'E Elcana se voltou a sua casa em Ramá; e o menino ministrava ao SENHOR diante do sacerdote Eli.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 12, 'Mas os filhos de Eli eram homens ímpios, e não tinham conhecimento do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 13, 'E o costume dos sacerdotes com o povo era que, quando alguém oferecia sacrifício, vinha o criado do sacerdote enquanto a carne estava a cozer, trazendo em sua mão um garfo de três ganchos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 14, 'E enfiava com ele na caldeira, ou na caçarola, ou no caldeirão, ou no pote; e tudo o que tirava o garfo, o sacerdote o tomava para si. Desta maneira faziam a todo israelita que vinha a Siló.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 15, 'Também, antes de queimar a gordura, vinha o criado do sacerdote, e dizia ao que sacrificava: Da carne que asse para o sacerdote; porque não tomará de ti carne cozida, mas sim crua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 16, 'E se lhe respondia o homem, Queimem logo a gordura hoje, e depois toma tanta quanto quiseres; ele respondia: Não, mas sim agora a darás: de outra maneira eu a tomarei por força.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 17, 'Era, pois, o pecado dos moços muito grande diante do SENHOR; porque os homens menosprezavam os sacrifícios do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 18, 'E o jovem Samuel ministrava diante do SENHOR, vestido de um éfode de linho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 19, 'E fazia-lhe sua mãe uma túnica pequena, e a trazia a ele a cada ano, quando subia com seu marido a oferecer o sacrifício costumeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 20, 'E Eli abençoou Elcana e a sua mulher, dizendo: “O SENHOR te dê descendência desta mulher por causa dessa petição que ela fez ao SENHOR.” E voltaram para sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 21, 'E o SENHOR visitou a Ana, e ela concebeu, e deu à luz três filhos e duas filhas. E o jovem Samuel crescia diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 22, 'Eli, porém, era muito velho, e ouviu tudo o que seus filhos faziam a todo Israel, e como se deitavam com as mulheres que serviam à porta do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 23, 'E disse-lhes: “Por que fazeis essas coisas? Pois eu ouço de todo este povo os vossos maus atos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 24, 'Não, meus filhos; pois não é boa a fama que eu ouço, que fazeis pecar ao povo do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 25, 'Se o homem pecar contra o homem, os juízes o julgarão; mas, se alguém pecar contra o SENHOR, quem rogará por ele?” Porém eles não ouviram a voz de seu pai, porque o SENHOR queria matá-los.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 26, 'E o jovem Samuel ia crescendo e sendo bem estimando diante de Deus e diante das pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 27, 'E veio um homem de Deus a Eli, e disse-lhe: “Assim diz o SENHOR: ‘Acaso não me manifestei à casa do teu pai, quando estavam no Egito, na casa de Faraó?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 28, 'E eu o escolhi para ser o meu sacerdote dentre todas as tribos de Israel, para que oferecesse sobre o meu altar, e queimasse incenso, e para que vestisse o éfode diante de mim; e dei à casa do teu pai todas as ofertas dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 29, 'Por que pisaste os meus sacrifícios e as minhas ofertas, que eu mandei oferecer no tabernáculo? E por que honraste aos teus filhos mais que a mim, para vos engordardes do principal de todas as ofertas do meu povo Israel?’'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 30, 'Por isso, o SENHOR, o Deus de Israel, diz: ‘Eu havia dito que a tua casa e a casa de teu pai andariam diante de mim perpetuamente;’ mas agora diz o SENHOR: ‘Longe de mim tal coisa, porque eu honrarei aos que me honram, e os que me desprezam serão rejeitados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 31, 'Eis que vêm dias em que cortarei o teu braço, e o braço da casa de teu pai, para que não haja idoso em tua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 32, 'E verás competidor no tabernáculo, em todas as coisas em que fizer bem a Israel; e em nenhum tempo haverá idoso em tua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 33, 'E não te cortarei de todo homem de meu altar, para fazer-te consumir os teus olhos, e encher teu ânimo de dor; mas toda a descendência de tua casa morrerá no princípio da fase adulta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 34, 'E te será por sinal isto que acontecerá a teus dois filhos, Hofni e Fineias: ambos morrerão em um dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 35, 'E eu suscitarei para mim um sacerdote fiel, que faça conforme o meu coração e a minha alma; e eu lhe edificarei casa firme, e andará diante de meu ungido todos os dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 2, 36, 'E será que o que houver restado em tua casa, virá a prostrar-se-lhe por um dinheiro de prata e um bocado de pão, dizendo-lhe: Rogo-te que me constituas em algum ministério, para que coma um bocado de pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 1, 'E o jovem Samuel ministrava ao SENHOR diante de Eli; e a palavra do SENHOR era rara naqueles dias; não havia visão manifesta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 2, 'E aconteceu um dia, que estando Eli deitado em seu aposento, quando seus olhos começavam a escurecer-se, que não podia ver,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 3, 'Samuel estava dormindo no templo do SENHOR, de onde a arca de Deus estava: e antes que a lâmpada de Deus fosse apagada,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 4, 'o SENHOR chamou a Samuel; e ele respondeu: Eis-me aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 5, 'E correndo logo a Eli, disse: Eis-me aqui; para que me chamaste? E Eli lhe disse: Eu não chamei; volta-te a deitar. E ele se voltou, e deitou-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 6, 'E o SENHOR voltou a chamar outra vez a Samuel. E levantando-se Samuel veio a Eli, e disse: Eis-me aqui; para que me chamaste? E ele disse: Filho meu, eu não chamei; volta, e deita-te.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 7, 'E Samuel não havia conhecido ainda ao SENHOR, nem a palavra do SENHOR lhe havia sido revelada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 8, 'O SENHOR, então, chamou pela terceira vez a Samuel. E ele levantando-se veio a Eli, e disse: Eis-me aqui; para que me chamaste? Então entendeu Eli que o SENHOR chamava ao jovem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 9, 'E disse Eli a Samuel: Vai, e deita-te: e se te chamar, dirás: Fala, SENHOR, que teu servo ouve. Assim se foi Samuel, e deitou-se em seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 10, 'E veio o SENHOR, e ficou ali, e chamou como das outras vezes: Samuel, Samuel! Então Samuel disse: Fala, que o teu servo está ouvindo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 11, 'E o SENHOR disse a Samuel: Eis que farei eu uma coisa em Israel, que a quem a ouvir, lhe retinirão ambos ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 12, 'Aquele dia eu despertarei contra Eli todas as coisas que disse sobre sua casa. Em começando, acabarei também.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 13, 'E lhe mostrarei que eu julgarei sua casa para sempre, pela iniquidade que ele sabe; porque seus filhos se corromperam, e ele não os repreendeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 14, 'E portanto eu jurei à casa de Eli, que a iniquidade da casa de Eli não será expiada jamais, nem com sacrifícios nem com ofertas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 15, 'E Samuel esteve deitado até a manhã, e abriu as portas da casa do SENHOR. E Samuel temia revelar a visão a Eli.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 16, 'Chamando, pois, Eli a Samuel, disse-lhe: Filho meu, Samuel. E ele respondeu: Eis-me aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 17, 'E disse: Que é a palavra que te falou o SENHOR? Rogo-te que não a encubras a mim; assim te faça Deus e assim te acrescente, se me encobrires palavra de tudo o que falou contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 18, 'E Samuel se o manifestou tudo, sem encobrir-lhe nada. Então ele disse: o SENHOR é; faça o que bem lhe parecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 19, 'E Samuel cresceu, e o SENHOR foi com ele, e não deixou cair por terra nenhuma de suas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 20, 'E conheceu todo Israel desde Dã até Berseba, que Samuel era fiel profeta do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 3, 21, 'Assim voltou o SENHOR a aparecer em Siló: porque o SENHOR se manifestou a Samuel em Siló com palavra do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 1, 'E Samuel falou a todo Israel. Por aquele tempo saiu Israel a encontrar em batalha aos filisteus, e assentou campo junto a Ebenézer, e os filisteus assentaram o seu em Afeque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 2, 'E os filisteus apresentaram a batalha a Israel; e travando-se o combate, Israel foi vencido diante dos filisteus, os quais feriram na batalha pelo campo como quatro mil homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 3, 'E voltado que houve o povo ao acampamento, os anciãos de Israel disseram: Por que nos feriu hoje o SENHOR diante dos filisteus? Tragamos a nós de Siló a arca do pacto do SENHOR, para que vindo entre nós nos salve da mão de nossos inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 4, 'E enviou o povo a Siló, e trouxeram dali a arca do pacto do SENHOR dos exércitos, que estava assentado entre os querubins; e os dois filhos de Eli, Hofni e Fineias, estavam ali com a arca do pacto de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 5, 'E aconteceu que, quando a arca do pacto do SENHOR veio ao campo, todo Israel deu grito com tão grande júbilo, que a terra tremeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 6, 'E quando os filisteus ouviram a voz de júbilo, disseram: Que voz de grande júbilo é esta no campo dos hebreus? E souberam que a arca do SENHOR havia vindo ao campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 7, 'E os filisteus tiveram medo, porque diziam: Veio Deus ao campo. E disseram: Ai de nós! pois antes de agora não foi assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 8, 'Ai de nós! Quem nos livrará das mãos destes deuses fortes? Estes são os deuses que feriram ao Egito com toda praga no deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 9, 'Esforçai-vos, ó filisteus, e sede homens, porque não sirvais aos hebreus, como eles vos serviram a vós: sede homens, e lutai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 10, 'Lutaram, pois, os filisteus, e Israel foi vencido, e fugiram cada qual a suas tendas; e foi feita muito grande mortandade, pois caíram de Israel trinta mil homens a pé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 11, 'E a arca de Deus foi tomada, e morreram os dois filhos de Eli, Hofni e Fineias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 12, 'E correndo da batalha um homem de Benjamim, veio naquele dia a Siló, com suas roupas rasgadas e com terra sobre sua cabeça:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 13, 'E quando chegou, eis que Eli que estava sentado em uma cadeira vigiando junto ao caminho; porque seu coração estava tremendo por causa da arca de Deus. Chegado pois aquele homem à cidade, e dadas as novas, toda a cidade gritou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 14, 'E quando Eli ouviu o estrondo da gritaria, disse: Que estrondo de alvoroço é este? E aquele homem veio depressa, e deu as novas a Eli.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 15, 'Era já Eli de idade de noventa e oito anos, e seus olhos se haviam entenebrecido, de modo que não podia ver.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 16, 'Disse, pois, aquele homem a Eli: Eu venho da batalha, eu escapei hoje do combate. E ele disse: Que aconteceu, filho meu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 17, 'E o mensageiro respondeu, e disse: Israel fugiu diante dos filisteus, e também foi feita grande mortandade no povo; e também teus dois filhos, Hofni e Fineias, são mortos, e a arca de Deus foi tomada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 18, 'E aconteceu que quando ele fez menção da arca de Deus, Eli caiu até atrás da cadeira ao lado da porta, e o seu pescoço se quebrou, e ele morreu: porque era homem velho e pesado. E havia julgado a Israel quarenta anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 19, 'E sua nora, a mulher de Fineias, que estava grávida, próxima ao parto, ouvindo a notícia que a arca de Deus havia sido tomada, e mortos seu sogro e seu marido, encurvou-se e teve o parto; porque suas dores vieram sobre ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 20, 'E ao tempo em que morria, diziam-lhe as que estavam junto a ela: Não tenhas medo, porque deste à luz um filho. Mas ela não respondeu, nem deu atenção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 21, 'E chamou ao menino Icabode, dizendo: Passada foi a glória de Israel! Por causa arca de Deus que foi tomada, e porque era morto seu sogro, e seu marido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 4, 22, 'Disse, pois: Passada foi a glória de Israel; porque a arca de Deus foi tomada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 5, 1, 'E os filisteus, depois de tomarem a arca de Deus, trouxeram-na desde Ebenézer a Asdode.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 5, 2, 'E tomaram os filisteus a arca de Deus, e meteram-na na casa de Dagom, e puseram-na junto a Dagom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 5, 3, 'E o seguinte dia os de Asdode se levantaram de manhã, e eis Dagom prostrado em terra diante da arca do SENHOR: e tomaram a Dagom, e voltaram-no a seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 5, 4, 'E voltando-se a levantar de manhã o dia seguinte, eis que Dagom havia caído prostrado em terra diante da arca do SENHOR; e a cabeça de Dagom, e as duas palmas de suas mãos estavam cortadas sobre o umbral, havendo restado a Dagom o tronco somente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 5, 5, 'Por esta causa os sacerdotes de Dagom, e todos os que no templo de Dagom entram, não pisam o umbral de Dagom em Asdode, até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 5, 6, 'Porém agravou-se a mão do SENHOR sobre os de Asdode, e assolou-os, e feriu-os com chagas em Asdode e em todos seus termos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 5, 7, 'E vendo isto os de Asdode, disseram: Não fique conosco a arca do Deus de Israel, porque sua mão é dura sobre nós, e sobre nosso deus Dagom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 5, 8, 'Mandaram, pois, juntar a si todos os príncipes dos filisteus, e disseram: Que faremos da arca do Deus de Israel? E eles responderam: Passe-se a arca do Deus de Israel a Gate. E passaram ali a arca do Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 5, 9, 'E aconteceu que quando a houveram passado, a mão do SENHOR foi contra a cidade com grande tormento; e feriu os homens daquela cidade desde o pequeno até o grande, que se encheram de chagas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 5, 10, 'Então enviaram a arca de Deus a Ecrom. E quando a arca de Deus veio a Ecrom, os ecronitas deram vozes dizendo: Passaram a mim a arca do Deus de Israel para matar a mim e a meu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 5, 11, 'E enviaram a juntar todos os príncipes dos filisteus, dizendo: Despachai a arca do Deus de Israel, e torne-se a seu lugar, e não mate a mim nem a meu povo: porque havia tormento de morte em toda a cidade, e a mão de Deus se havia ali agravado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 5, 12, 'E os que não morriam, eram feridos de chagas; e o clamor da cidade subia ao céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 1, 'E esteve a arca do SENHOR na terra dos filisteus sete meses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 2, 'Então os filisteus, chamando os sacerdotes e adivinhos, perguntaram: Que faremos da arca do SENHOR? Declarai-nos como a devemos tornar a enviar a seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 3, 'E eles disseram: Se enviais a arca do Deus de Israel, não a envieis vazia; mas lhe pagareis a expiação: e então sereis sãos, e conhecereis por que não se afastou de vós sua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 4, 'E eles disseram: E que será a expiação que lhe pagaremos? E eles responderam: Conforme o número dos príncipes dos filisteus, cinco chagas de ouro, e cinco ratos de ouro, porque a mesma praga que todos têm, têm também vossos príncipes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 5, 'Fareis, pois, as formas de vossas chagas, e as formas de vossos ratos que destroem a terra, e dareis glória ao Deus de Israel: talvez aliviará sua mão de sobre vós, e de sobre vossos deuses, e de sobre vossa terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 6, 'Mas por que endureceis vosso coração, como os egípcios e Faraó endureceram seu coração? Depois que os houve assim tratado, não os deixaram que se fossem, e se foram?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 7, 'Fazei, pois, agora um carro novo, e tomai logo duas vacas que criem, às quais não haja sido posto jugo, e preparai as vacas ao carro, e fazei voltar de detrás delas seus bezerros a casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 8, 'Tomareis logo a arca do SENHOR, e a poreis sobre o carro; e ponde em uma caixa ao lado dela as joias de ouro que lhe pagais em expiação: e a deixareis que se vá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 9, 'E olhai: se sobe pelo caminho de seu termo a Bete-Semes, ele nos fez este mal tão grande; e se não, teremos certeza de que não foi sua mão que nos feriu, mas nos foi coincidência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 10, 'E aqueles homens o fizeram assim; pois tomando duas vacas que criavam, prepararam-nas ao carro, e encerraram em casa seus bezerros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 11, 'Logo puseram a arca do SENHOR sobre o carro, e a caixa com os ratos de ouro e com as formas de suas chagas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 12, 'E as vacas se encaminharam pelo caminho de Bete-Semes, e iam por um mesmo caminho andando e bramando, sem desviar-se nem à direita nem à esquerda: e os príncipes dos filisteus foram atrás elas até o termo de Bete-Semes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 13, 'E os de Bete-Semes ceifavam o trigo no vale; e levantando seus olhos viram a arca, e alegraram-se quando a viram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 14, 'E o carro veio ao campo de Josué Bete-Semita, e parou ali porque ali havia uma grande pedra; e eles cortaram a madeira do carro, e ofereceram as vacas em holocausto ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 15, 'E os levitas baixaram a arca do SENHOR, e a caixa que estava junto a ela, na qual estavam as joias de ouro, e puseram-nas sobre aquela grande pedra; e os homens de Bete-Semes sacrificaram holocaustos e mataram vítimas ao SENHOR naquele dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 16, 'O qual vendo os cinco príncipes dos filisteus, voltaram a Ecrom o mesmo dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 17, 'Estas, pois, são as chagas de ouro que pagaram os filisteus ao SENHOR em expiação: por Asdode uma, por Gaza uma, por Asquelom uma, por Gate uma, por Ecrom uma;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 18, 'E ratos de ouro conforme ao número de todas as cidades dos filisteus pertencentes aos cinco príncipes, desde as cidades fortes até as aldeias sem muro; e até a grande pedra sobre a qual puseram a arca do SENHOR, pedra que está no campo de Josué, bete-semita, até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 19, 'Então feriu Deus aos de Bete-Semes, porque haviam olhado no arca do SENHOR; feriu no povo cinquenta mil e setenta homens. E o povo pôs luto, porque o SENHOR lhe havia ferido de tão grande praga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 20, 'E disseram os de Bete-Semes: Quem poderá estar diante do SENHOR o Deus santo? e a quem subirá desde nós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 6, 21, 'E enviaram mensageiros aos de Quriate-Jearim, dizendo: Os filisteus devolveram a arca do SENHOR: descei, pois, e levai-a a vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 7, 1, 'E vieram os de Quriate-Jearim, e levaram a arca do SENHOR, e meteram-na em casa de Abinadabe, situada no morro; e santificaram a Eleazar seu filho, para que guardasse a arca do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 7, 2, 'E aconteceu que desde o dia que chegou a arca a Quriate-Jearim passaram muito dias, vinte anos; e toda a casa de Israel se lamentou, voltando a seguir o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 7, 3, 'E falou Samuel a toda a casa de Israel, dizendo: Se de todo vosso coração vos volteis ao SENHOR, tirai os deuses alheios e a Astarote de entre vós, e preparai vosso coração ao SENHOR, e a somente ele servi, e vos livrará da mão dos filisteus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 7, 4, 'Então os filhos de Israel tiraram aos baalins e a Astarote, e serviram a somente o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 7, 5, 'E Samuel disse: Juntai a todo Israel em Mispá, e eu orarei por vós ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 7, 6, 'E juntando-se em Mispá, tiraram água, e derramaram-na diante do SENHOR, e jejuaram aquele dia, e disseram ali: Contra o SENHOR temos pecado. E julgou Samuel aos filhos de Israel em Mispá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 7, 7, 'E ouvindo os filisteus que os filhos de Israel estavam reunidos em Mispá, subiram os príncipes dos filisteus contra Israel: o qual quando houveram ouvido os filhos de Israel, tiveram temor dos filisteus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 7, 8, 'E disseram os filhos de Israel a Samuel: Não cesses de clamar por nós ao SENHOR nosso Deus, que nos guarde da mão dos filisteus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 7, 9, 'E Samuel tomou um cordeiro que ainda amamentava, e sacrificou-o inteiro ao SENHOR em holocausto: e clamou Samuel ao SENHOR por Israel, e o SENHOR lhe ouviu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 7, 10, 'E aconteceu que estando Samuel sacrificando o holocausto, os filisteus chegaram para lutar com os filhos de Israel. Mas o SENHOR trovejou aquele dia com grande estrondo sobre os filisteus, e desbaratou-os, e foram vencidos diante de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 7, 11, 'E saindo os filhos de Israel de Mispá, seguiram aos filisteus, ferindo-os até abaixo de Bete-Car.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 7, 12, 'Tomou logo Samuel uma pedra, e a pôs entre Mispá e Sem, e pôs-lhe por nome Ebenézer, dizendo: Até aqui nos ajudou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 7, 13, 'Foram, pois, os filisteus humilhados, que não vieram mais ao termo de Israel; e a mão do SENHOR foi contra os filisteus todo o tempo de Samuel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 7, 14, 'E foram restituídas aos filhos de Israel as cidades que os filisteus haviam tomado aos israelitas, desde Ecrom até Gate, com seus termos: e Israel as livrou da mão dos filisteus. E houve paz entre Israel e o amorreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 7, 15, 'E julgou Samuel a Israel todo o tempo que viveu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 7, 16, 'E todos os anos ia e dava volta a Betel, e a Gilgal, e a Mispá, e julgava a Israel em todos estes lugares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 7, 17, 'Voltava-se depois a Ramá, porque ali estava sua casa, e ali julgava a Israel; e edificou ali altar ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 1, 'E aconteceu que havendo Samuel envelhecido, pôs seus filhos por juízes sobre Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 2, 'E o nome de seu filho primogênito foi Joel, e o nome do segundo, Abias: foram juízes em Berseba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 3, 'Mas não andaram os filhos pelos caminhos de seu pai, antes se inclinaram atrás a ganância, recebendo suborno e pervertendo o direito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 4, 'Então todos os anciãos de Israel se juntaram, e vieram a Samuel em Ramá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 5, 'E disseram-lhe: Eis que tu envelheceste, e teus filhos não vão por teus caminhos: portanto, constitui-nos agora um rei que nos julgue, como todas as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 6, 'E descontentou a Samuel esta palavra que disseram: Dá-nos rei que nos julgue. E Samuel orou ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 7, 'E disse o SENHOR a Samuel: Ouve a voz do povo em tudo o que te disserem: porque não rejeitaram a ti, mas sim a mim me rejeitaram, para que eu não reine sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 8, 'Conforme todas as obras que fizeram desde o dia que os tirei do Egito até hoje, que me deixaram e serviram a deuses alheios, assim fazem também contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 9, 'Agora, pois, ouve sua voz: mas protesta contra eles declarando-lhes o direito do rei que há de reinar sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 10, 'E disse Samuel todas as palavras do SENHOR ao povo que lhe havia pedido rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 11, 'Disse, pois: Este será o direito do rei que houver de reinar sobre vós: tomará vossos filhos, e os porá em seus carros, e em seus cavaleiros, para que corram diante de seu carro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 12, 'E se escolherá capitães de mil, e capitães de cinquenta: os porá também a que arem seus campos, e ceifem suas plantações, e a que façam suas armas de guerra, e os equipamentos de seus carros:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 13, 'Tomará também vossas filhas para que sejam perfumistas, cozinheiras, e padeiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 14, 'Também tomará vossas terras, vossas vinhas, e vossos bons olivais, e os dará a seus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 15, 'Ele tomará o dízimo de vossas sementes e vossas vinhas, para dar a seus eunucos e a seus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 16, 'Ele tomará vossos servos, e vossas servas, e vossos bons rapazes, e vossos asnos, e com eles fará suas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 17, 'Tomará o dízimo também do vosso rebanho, e sereis seus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 18, 'E clamareis aquele dia por causa de vosso rei que vos havereis escolhido, mas o SENHOR não vos ouvirá naquele dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 19, 'Porém o povo não quis ouvir a voz de Samuel; antes disseram: Não, mas sim que haverá rei sobre nós:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 20, 'E nós seremos também como todas as nações, e nosso rei nos governará, e sairá diante de nós, e fará nossas guerras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 21, 'E ouviu Samuel todas as palavras do povo, e referiu-as aos ouvidos do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 8, 22, 'E o SENHOR disse a Samuel: Ouve sua voz, e põe rei sobre eles. Então disse Samuel aos homens de Israel: Ide-vos cada um à sua cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 1, 'E havia um homem de Benjamim, homem valente, o qual se chamava Quis, filho de Abiel, filho de Zeror, filho de Becorate, filho de Afia, filho de um homem de Benjamim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 2, 'E tinha ele um filho que se chamava Saul, rapaz e belo, que entre os filhos de Israel não havia outro mais belo que ele; do ombro acima sobrepujava a qualquer um do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 3, 'E haviam-se perdido as asnas de Quis, pai de Saul; pelo que disse Quis a Saul seu filho: Toma agora contigo algum dos criados, e levanta-te, e vai a buscar as asnas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 4, 'E ele passou ao monte de Efraim, e dali à terra de Salisa, e não as acharam. Passaram logo pela terra de Saalim, e tampouco. Depois passaram pela terra de Benjamim, e não as encontraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 5, 'E quando vieram à terra de Zufe, Saul disse a seu criado que tinha consigo: Vem, voltemo-nos; porque talvez meu pai, deixado o cuidado das asnas, estará aflito por nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 6, 'E ele lhe respondeu: Eis que agora há nesta cidade um homem de Deus, que é homem ilustre: todas as coisas que ele disser, sem dúvida virão a suceder. Vamos pois ali; talvez nos ensinará nosso caminho por onde havemos de ir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 7, 'E Saul respondeu a seu criado: Vamos agora: mas que levaremos ao homem? Porque o pão de nossos alforjes se acabou, e não temos que presentear ao homem de Deus: que temos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 8, 'Então voltou o criado a responder a Saul, dizendo: Eis que se acha em minha mão a quarta parte de um siclo de prata: isto darei ao homem de Deus, porque nos declare nosso caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 9, '(Antigamente em Israel qualquer um que ia a consultar a Deus, dizia assim: Vinde e vamos até o vidente: porque o que agora se chama profeta, antigamente era chamado vidente).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 10, 'Disse então Saul a seu criado: Bem dizes; eia, pois, vamos. E foram à cidade de onde estava o homem de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 11, 'E quando subiam pela encosta da cidade, acharam umas moças que saíam por água, às quais disseram: Está neste lugar o vidente?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 12, 'E elas respondendo-lhes, disseram: Sim; ei-lo aqui diante de ti: apressa-te, pois, porque hoje veio à cidade porque o povo tem hoje sacrifício no alto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 13, 'E quando entrardes na cidade, vós o encontrareis logo, antes que suba ao alto a comer; pois o povo não comerá até que ele tenha vindo, porquanto ele deve abençoar o sacrifício, e depois comerão os convidados. Subi, pois agora, porque agora o achareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 14, 'Eles então subiram à cidade; e quando em meio da cidade estiveram, eis que Samuel que diante deles saía para subir ao alto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 15, 'E um dia antes que Saul viesse, o SENHOR havia revelado ao ouvido de Samuel, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 16, 'Amanhã a esta mesma hora eu enviarei a ti um homem da terra de Benjamim, ao qual ungirás por príncipe sobre meu povo Israel, e salvará meu povo da mão dos filisteus: pois eu olhei a meu povo, porque seu clamor há chegado até mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 17, 'E logo que Samuel viu a Saul, o SENHOR lhe disse: Eis que este é o homem do qual te falei; este dominará a meu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 18, 'E chegando Saul a Samuel em meio da porta, disse-lhe: Rogo-te que me ensines onde está a casa do vidente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 19, 'E Samuel respondeu a Saul, e disse: Eu sou o vidente: sobe diante de mim ao alto, e comei hoje comigo, e pela manhã te despacharei, e te revelarei tudo o que está em teu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 20, 'E das asnas que se te perderam hoje há três dias, deixa de se preocupar com elas, porque se acharam. Mas a quem é todo o desejo de Israel, se não a ti e a toda a casa de teu pai?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 21, 'E Saul respondeu, e disse: Não sou eu filho de Benjamim, das menores tribos de Israel? e minha família não é a mais pequena de todas as famílias da tribo de Benjamim? por que pois me disseste coisa semelhante?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 22, 'E tomando Samuel a Saul e a seu criado, meteu-os na sala, e deu-lhes lugar à cabeceira dos convidados, que eram como uns trinta homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 23, 'E disse Samuel ao cozinheiro: Traze aqui a porção que te dei, a qual te disse que guardasses à parte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 24, 'Então levantou o cozinheiro uma coxa, com o que estava sobre ela, e a pôs diante de Saul. E Samuel disse: Eis que o que estava reservado: põe-o diante de ti, e come; porque foi intencionalmente guardado para ti, quando disse: Eu convidei ao povo. E Saul comeu aquele dia com Samuel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 25, 'E quando houveram descido do alto à cidade, ele falou com Saul no terraço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 26, 'E ao outro dia madrugaram: e quando ao raiar da alva, Samuel chamou a Saul, que estava no terraço; e disse: Levanta-te, para que te despache. Levantou-se logo Saul, e saíram fora ambos, ele e Samuel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 9, 27, 'E descendo eles ao fim da cidade, disse Samuel a Saul: Dize ao jovem que vá diante, (e adiantou-se o jovem); mas espera tu um pouco para que te declare palavra de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 1, 'Tomando então Samuel um frasco de azeite, derramou-o sobre sua cabeça, e beijou-o, e disse-lhe: Não foi o SENHOR que te ungiu para que sejas líder sobre sua propriedade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 2, 'Hoje, depois que te tenhas apartado de mim, acharás dois homens junto ao sepulcro de Raquel, no termo de Benjamim, em Zelza, os quais te dirão: As asnas que havias ido a buscar, se acharam; teu pai pois há deixado já o negócio das asnas, porém está preocupado convosco, dizendo: Que farei acerca de meu filho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 3, 'E quando dali te fores mais adiante, e chegares à campina de Tabor, te sairão ao encontro três homens que sobem a Deus em Betel, levando o um três cabritos, e o outro três tortas de pão, e o terceiro uma vasilha de vinho:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 4, 'Os quais, logo que te tenham saudado, te darão dois pães, os quais tomarás das mãos deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 5, 'De ali virás ao morro de Deus de onde está a guarnição dos filisteus; e quando entrares ali na cidade encontrarás uma companhia de profetas que descem do alto, e diante deles saltério, e adufe, e flauta, e harpa, e eles profetizando:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 6, 'E o espírito do SENHOR te arrebatará, e profetizarás com eles, e serás transformado em outro homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 7, 'E quando te houverem sobrevindo estas sinais, faze o que te vier à mão, porque Deus é contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 8, 'E descerás antes de mim a Gilgal; e logo descerei eu a ti para sacrificar holocaustos, e imolar sacrifícios pacíficos. Espera sete dias, até que eu venha a ti, e te ensine o que hás de fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 9, 'E foi que assim quando virou ele seu ombro para partir-se de Samuel, mudou-lhe Deus seu coração; e todas estes sinais aconteceram naquele dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 10, 'E quando chegaram ali ao morro, eis que a companhia dos profetas que vinha a encontrar-se com ele, e o Espírito de Deus o arrebatou, e profetizou entre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 11, 'E aconteceu que, quando todos os que o conheciam de antes viram como profetizava com os profetas, o povo dizia o um ao outro: Que sucedeu ao filho de Quis? Saul também entre os profetas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 12, 'E algum dali respondeu, e disse: E quem é o pai deles? Por esta causa se tornou em provérbio: Também Saul entre os profetas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 13, 'E cessou de profetizar, e chegou ao alto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 14, 'E um tio de Saul disse a ele e a seu criado: Aonde fostes? E ele respondeu: A buscar as asnas; e quando vimos que não apareciam, fomos a Samuel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 15, 'E disse o tio de Saul: Eu te rogo me declares que vos disse Samuel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 16, 'E Saul respondeu a seu tio: Declarou-nos expressamente que as asnas haviam aparecido. Mas do negócio do reino, de que Samuel lhe havia falado, não lhe revelou nada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 17, 'E Samuel convocou o povo ao SENHOR em Mispá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 18, 'E disse aos filhos de Israel: Assim disse o SENHOR o Deus de Israel: Eu tirei a Israel do Egito, e vos livre da mão dos egípcios, e da mão de todos os reinos que vos afligiram:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 19, 'Mas vós rejeitastes hoje a vosso Deus, que vos guarda de todas as vossas aflições e angústias, e dissestes: Não, mas sim põe rei sobre nós. Agora pois, ponde-vos diante do SENHOR por vossas tribos e por vossos milhares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 20, 'E fazendo achegar Samuel todas as tribos de Israel, foi tomada a tribo de Benjamim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 21, 'E fez chegar a tribo de Benjamim por suas linhagens, e foi tomada a família de Matri; e dela foi tomado Saul filho de Quis. E lhe buscaram, mas não foi achado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 22, 'Perguntaram pois outra vez ao SENHOR, se havia ainda de vir ali aquele homem. E respondeu o SENHOR: Eis que ele está escondido entre a bagagem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 23, 'Então correram, e tomaram-no dali, e posto em meio do povo, desde o ombro acima era mais alto que todo o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 24, 'E Samuel disse a todo o povo: Vistes ao que o SENHOR escolheu, que não há semelhante a ele em todo o povo? Então o povo clamou com alegria, dizendo: Viva o rei!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 25, 'Então Samuel recitou ao povo o direito do reino, e escreveu-o em um livro, o qual guardou diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 26, 'E enviou Samuel a todo o povo cada um a sua casa. E Saul também se foi a sua casa em Gibeá, e foram com ele o exército, o coração dos quais Deus havia tocado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 10, 27, 'Porém os ímpios disseram: Como nos há de salvar este? E tiveram-lhe em pouco, e não lhe trouxeram presente: mas ele dissimulou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 11, 1, 'E subiu Naás amonita, e assentou acampamento contra Jabes de Gileade. E todos os de Jabes disseram a Naás: Faze aliança conosco, e te serviremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 11, 2, 'E Naás amonita lhes respondeu: Com esta condição farei aliança convosco, que a cada um de todos vós tire o olho direito, e ponha esta afronta sobre todo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 11, 3, 'Então os anciãos de Jabes lhe disseram: Dá-nos sete dias, para que enviemos mensageiros a todos os termos de Israel; e se ninguém houver que nos defenda, sairemos a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 11, 4, 'E chegando os mensageiros a Gibeá de Saul, disseram estas palavras em ouvidos do povo; e todo o povo chorou a voz em grito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 11, 5, 'E eis que Saul que vinha do campo, atrás os bois; e disse Saul: Que tem o povo, que choram? E contaram-lhe as palavras dos homens de Jabes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 11, 6, 'E o espírito de Deus arrebatou a Saul em ouvindo estas palavras, e acendeu-se em ira em grande maneira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 11, 7, 'E tomando um par de bois, cortou-os em peças, e enviou-as por todos os termos de Israel por meio de mensageiros, dizendo: Qualquer um que não sair após Saul e após Samuel, assim será feito a seus bois. E caiu temor do SENHOR sobre o povo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 11, 8, 'E contou-lhes em Bezeque; e foram os filhos de Israel trezentos mil, e trinta mil os homens de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 11, 9, 'E responderam aos mensageiros que haviam vindo: Assim direis aos de Jabes de Gileade: Amanhã em aquecendo o sol, tereis salvamento. E vieram os mensageiros, e declararam-no aos de Jabes, os quais se alegraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 11, 10, 'E os de Jabes disseram: Amanhã sairemos a vós, para que façais conosco tudo o que bem vos parecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 11, 11, 'E o dia seguinte dispôs Saul o povo em três esquadrões, e entraram em meio do acampamento à vigília da manhã, e feriram aos amonitas até que o dia aquecesse; e os que restaram foram dispersos, tal que não restaram dois deles juntos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 11, 12, 'O povo então disse a Samuel: Quem são o que diziam: Reinará Saul sobre nós? Dai-nos esses homens, e os mataremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 11, 13, 'E Saul disse: Não morrerá hoje ninguém, porque hoje operou o SENHOR salvação em Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 11, 14, 'Mas Samuel disse ao povo: Vinde, vamos a Gilgal para que renovemos ali o reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 11, 15, 'E foi todo o povo a Gilgal, e investiram ali a Saul por rei diante do SENHOR em Gilgal. E sacrificaram ali vítimas pacíficas diante do SENHOR; e alegraram-se muito ali Saul e todos os de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 1, 'E disse Samuel a todo Israel: Eis que, eu ouvi vossa voz em todas as coisas que me haveis dito, e vos pus rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 2, 'Agora, pois, eis que vosso rei vai diante de vós. Eu sou já velho e grisalho: mas meus filhos estão convosco, e eu andei diante de vós desde minha juventude até este dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 3, 'Aqui estou; testemunhai contra mim diante do SENHOR e diante de seu ungido, se tomei o boi de alguém, ou se tomei o asno de alguém, ou se caluniei a alguém, ou se oprimi a alguém, ou se de alguém tomei suborno pelo qual tenha coberto meus olhos; e eu vos restituirei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 4, 'Então disseram: Nunca nos caluniaste, nem oprimi, nem tomaste algo da mão de nenhum homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 5, 'E ele lhes disse: o SENHOR é testemunha contra vós, e seu ungido também é testemunha neste dia, que não achastes em minha mão coisa nenhuma. E eles responderam: Assim é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 6, 'Então Samuel disse ao povo: o SENHOR é quem fez a Moisés e a Arão, e que tirou a vossos pais da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 7, 'Agora, pois, aguardai, e eu queixarei de vós diante do SENHOR de todas as justiças do SENHOR, que fez convosco e com vossos pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 8, 'Depois que Jacó entrou em Egito e vossos pais clamaram ao SENHOR, o SENHOR enviou a Moisés e a Arão, os quais tiraram a vossos pais do Egito, e os fizeram habitar neste lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 9, 'E esqueceram ao SENHOR seu Deus, e ele os vendeu na mão de Sísera capitão do exército de Hazor, e na mão dos filisteus, e na mão do rei de Moabe, os quais lhes fizeram guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 10, 'E eles clamaram ao SENHOR, e disseram: Pecamos, porque deixamos ao SENHOR, e servimos aos baalins e a Astarote: livra-nos, pois, agora da mão de nossos inimigos, e te serviremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 11, 'Então o SENHOR enviou a Jerubaal, e a Bedã, e a Jefté, e a Samuel, e vos livrou da mão de vossos inimigos ao redor, e habitastes seguros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 12, 'E havendo visto que Naás rei dos filhos de Amom vinha contra vós, me dissestes: Não, mas sim rei reinará sobre nós; sendo vosso rei o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 13, 'Agora, pois, vede aqui vosso rei que haveis escolhido, o qual pedistes; já vedes que o SENHOR pôs sobre vós rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 14, 'Se temerdes ao SENHOR e o servirdes, e ouvirdes sua voz, e não fordes rebeldes à palavra do SENHOR, tanto vós como o rei que rainha sobre vós, seguireis ao SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 15, 'Mas se não ouvirdes a voz do SENHOR, e se fordes rebeldes às palavras do SENHOR, a mão do SENHOR será contra vós como contra vossos pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 16, 'Esperai ainda agora, e olhai esta grande coisa que o SENHOR fará diante de vossos olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 17, 'Não é agora a colheita dos trigos? Eu clamarei ao SENHOR, e ele dará trovões e chuva; para que conheçais e vejais que é grande vossa maldade que tendes feito aos olhos do SENHOR, pedindo-vos rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 18, 'E Samuel clamou ao SENHOR; e o SENHOR deu trovões e chuva naquele dia; e todo o povo temeu em grande maneira ao SENHOR e a Samuel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 19, 'Então disse todo o povo a Samuel: Roga por teus servos ao SENHOR teu Deus, que não morramos: porque a todos os nossos pecados acrescentamos este mal de pedir rei para nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 20, 'E Samuel respondeu ao povo: Não temais: vós cometestes todo este mal; mas com tudo isso não vos desvieis de seguir ao SENHOR, mas sim servi ao SENHOR com todo o vosso coração:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 21, 'Não vos desvieis a fim de seguir as vaidades que não aproveitam nem livram, porque são vaidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 22, 'Pois o SENHOR não desamparará a seu povo por seu grande nome: porque o SENHOR quis fazer-vos povo seu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 23, 'Assim que, longe seja de mim que peque eu contra o SENHOR cessando de rogar por vós; antes eu vos ensinarei pelo caminho bom e direito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 24, 'Somente temei ao SENHOR, e servi-o de verdade com todo vosso coração, porque considerai quão grandes coisas fez convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 12, 25, 'Mas se perseverardes em fazer mal, vós e vosso rei perecereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 13, 1, 'Havia já Saul reinado um ano; e reinado que houve dois anos sobre Israel,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 13, 2, 'Escolheu-se logo três mil de Israel: os dois mil estiveram com Saul em Micmás e no monte de Betel, e os mil estiveram com Jônatas em Gibeá de Benjamim; e enviou a todo o outro povo cada um a suas tendas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 13, 3, 'E Jônatas feriu a guarnição dos filisteus que havia no morro, e ouviram-no os filisteus. E fez Saul tocar trombetas por toda a terra, dizendo: Ouçam os hebreus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 13, 4, 'E todo Israel ouviu o que se dizia: Saul feriu a guarnição dos filisteus; e também que Israel se tornou detestável aos filisteus. E juntou-se o povo sob o comando de Saul em Gilgal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 13, 5, 'Então os filisteus se juntaram para lutar com Israel, trinta mil carros, e seis mil cavalos, e povo quando a areia que está à beira do mar em multidão; e subiram, e assentaram acampamento em Micmás, ao oriente de Bete-Áven.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 13, 6, 'Mas os homens de Israel, vendo-se postos em apuros, (porque o povo estava em dificuldades), escondeu-se o povo em covas, em fossos, em penhascos, em rochas e em cisternas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 13, 7, 'E alguns dos hebreus passaram o Jordão à terra de Gade e de Gileade: e Saul se estava ainda em Gilgal, e todo o povo ia atrás dele tremendo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 13, 8, 'E ele esperou sete dias, conforme ao prazo que Samuel havia dito; mas Samuel não vinha a Gilgal, e o povo se lhe desertava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 13, 9, 'Então disse Saul: Trazei-me holocausto e sacrifícios pacíficos. E ofereceu o holocausto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 13, 10, 'E quando ele acabava de fazer o holocausto, eis que Samuel que vinha; e Saul lhe saiu a receber para saudar-lhe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 13, 11, 'Então Samuel disse: Que fizeste? E Saul respondeu: Porque vi que o povo se me ia, e que tu não vinhas ao prazo dos dias, e que os filisteus estavam juntos em Micmás,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 13, 12, 'Disse-me: Os filisteus descerão agora contra mim a Gilgal, e eu não implorei o favor do SENHOR. Esforcei-me pois, e ofereci holocausto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 13, 13, 'Então Samuel disse a Saul: Loucamente fizeste; não guardaste o mandamento do SENHOR teu Deus, que ele te havia intimado; porque agora o SENHOR teria confirmado teu reino sobre Israel para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 9, '1 Samuel', '1Sm', 13, 14, 'Mas agora teu reino não será durável: o SENHOR buscou para si homem segundo seu coração, ao qual o SENHOR mandou que seja líder sobre seu povo, porquanto tu não guardaste o que o SENHOR te mandou.')
